from __future__ import annotations
from itertools import product

def words(n: int) -> list[str]:
    return ["".join(x) for x in product("01", repeat=n)]

def short_words(n: int) -> list[str]:
    return [w for j in range(n) for w in words(j)]

def show_collision(n: int = 5) -> None:
    """Demonstrate a collision in an attempted strictly-short encoding."""
    source, target = words(n), short_words(n)
    assigned: dict[str, str] = {}
    for i, word in enumerate(source):
        code = target[i % len(target)]
        if code in assigned:
            print(f"{assigned[code]} and {word} collide at {code!r}")
            return
        assigned[code] = word

if __name__ == "__main__":
    show_collision()

