from __future__ import annotations
from collections.abc import Hashable, Iterable
from typing import TypeVar
T = TypeVar("T", bound=Hashable)
U = TypeVar("U", bound=Hashable)

def first_collision(items: Iterable[T], encode: callable) -> tuple[T, T, U] | None:
    previous: dict[U, T] = {}
    for item in items:
        code: U = encode(item)
        if code in previous:
            return previous[code], item, code
        previous[code] = item
    return None

from __future__ import annotations
from itertools import product
from collections.abc import Iterable

def first_missing_binary_word(depth: int, queried: Iterable[str]) -> str:
    queried_set = set(queried)
    if len(queried_set) >= 1 << depth:
        raise ValueError("sub-exhaustive transcript required")
    for bits in product("01", repeat=depth):
        word = "".join(bits)
        if word not in queried_set:
            return word
    raise RuntimeError("unreachable")

